import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function AdminPortal() {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(false);
  
  // Form state tracking fields including your new updates
  const [form, setForm] = useState({
    brand: '',
    name: '',
    color: '',
    numberPlate: '',
    pricePerHour: '',
    category: 'business',
    image: null
  });

  // Keep track of whether we are editing an existing car asset
  const [editingCarId, setEditingCarId] = useState(null);

  useEffect(() => {
    fetchFleet();
  }, []);

  const fetchFleet = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/cars');
      setCars(res.data);
    } catch (err) {
      console.error("Error loading fleet registries", err);
    }
  };

  // 1. Populates the input form fields with selection data to prepare for modifications
  const handleEditInit = (car) => {
    setEditingCarId(car._id);
    setForm({
      brand: car.brand,
      name: car.name,
      color: car.color,
      numberPlate: car.numberPlate,
      pricePerHour: car.pricePerHour || '',
      category: car.category || 'business',
      image: null // Keep null unless they intend to overwrite the existing asset file image binary
    });
    // Optional: scrolls view window smoothly to input area container boundary point
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 2. Handles clearing out forms if user switches modes manually or cancels
  const resetFormState = () => {
    setEditingCarId(null);
    setForm({ brand: '', name: '', color: '', numberPlate: '', pricePerHour: '', category: 'business', image: null });
  };

  // 3. Consolidated submit handler processing either updates or deployments smoothly
  const handleSubmitAsset = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('brand', form.brand);
    formData.append('name', form.name);
    formData.append('color', form.color);
    formData.append('numberPlate', form.numberPlate);
    formData.append('pricePerHour', form.pricePerHour);
    formData.append('category', form.category);
    if (form.image) formData.append('image', form.image);

    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}`, 'Content-Type': 'multipart/form-data' };

      if (editingCarId) {
        // Run PUT mapping execution endpoint to overwrite parameters safely inside server routing paths
        await axios.put(`http://localhost:5000/api/cars/${editingCarId}`, formData, { headers });
        alert('Car Asset Updated Successfully');
      } else {
        // Standard code flow targeting direct layout deployment runs
        await axios.post('http://localhost:5000/api/cars', formData, { headers });
        alert('Car Asset Deployed Successfully');
      }
      resetFormState();
      fetchFleet();
    } catch (err) {
      alert(err.response?.data?.message || 'Error processing fleet asset transactions');
    }
  };

  const handleStatusChange = async (carId, newStatus) => {
    try {
      const token = localStorage.getItem('token');
      await axios.put(`http://localhost:5000/api/cars/${carId}/status`, { status: newStatus }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchFleet();
    } catch (err) {
      alert('Failed updating system status configuration flag settings');
    }
  };

  const handleDeleteAsset = async (carId) => {
    if (!window.confirm("Are you sure you want to remove this vehicle asset permanently?")) return;
    try {
      const token = localStorage.getItem('token');
      await axios.delete(`http://localhost:5000/api/cars/${carId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchFleet();
    } catch (err) {
      alert('Error clearing selected asset structure database logs');
    }
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      {/* SIDE NAVIGATION LAYOUT SECTION */}
      <div className="w-64 bg-neutral-950 text-white p-6 space-y-8 flex flex-col">
        <div>
          <p className="text-yellow-400 font-bold text-xs uppercase tracking-widest">Control Plane</p>
          <h2 className="text-xl font-black tracking-tight uppercase">Admin Portal</h2>
        </div>
        <nav className="flex-grow space-y-1 text-sm font-semibold text-neutral-400">
          <button className="w-full text-left py-3 px-4 rounded transition hover:bg-neutral-900">📊 Overview</button>
          <button className="w-full text-left py-3 px-4 rounded transition bg-neutral-900 text-white">🚗 Manage Fleet</button>
          <button className="w-full text-left py-3 px-4 rounded transition hover:bg-neutral-900">👥 Customers Directory</button>
        </nav>
      </div>

      {/* CORE CONTROL CONSOLE WINDOW LAYOUT MESH AREA */}
      <div className="flex-grow p-10 max-w-5xl">
        
        {/* ADD / EDIT DYNAMIC FLEET ASSET CARD */}
        <div className="bg-white border rounded-xl p-8 shadow-sm mb-8">
          <h3 className="text-xl font-black uppercase text-neutral-900 tracking-tight mb-6">
            {editingCarId ? '🔧 Modify Existing Fleet Asset' : '➕ Add New Fleet Asset'}
          </h3>
          <form onSubmit={handleSubmitAsset} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <input type="text" placeholder="Brand (e.g. Toyota)" required value={form.brand} className="border border-gray-300 rounded p-3 text-sm focus:outline-none" onChange={e => setForm({...form, brand: e.target.value})} />
              <input type="text" placeholder="Model Name" required value={form.name} className="border border-gray-300 rounded p-3 text-sm focus:outline-none" onChange={e => setForm({...form, name: e.target.value})} />
              <input type="text" placeholder="Color" required value={form.color} className="border border-gray-300 rounded p-3 text-sm focus:outline-none" onChange={e => setForm({...form, color: e.target.value})} />
              <input type="text" placeholder="Number Plate Number" required value={form.numberPlate} className="border border-gray-300 rounded p-3 text-sm focus:outline-none" onChange={e => setForm({...form, numberPlate: e.target.value})} />
              <input type="number" placeholder="Price Per Hour (PKR)" required value={form.pricePerHour} className="border border-gray-300 rounded p-3 text-sm focus:outline-none" onChange={e => setForm({...form, pricePerHour: e.target.value})} />
              <select required value={form.category} className="border border-gray-300 bg-white rounded p-3 text-sm focus:outline-none text-gray-700" onChange={e => setForm({...form, category: e.target.value})}>
                <option value="business">Business</option>
                <option value="family">Family</option>
                <option value="adventure">Adventure</option>
                <option value="wedding">Wedding</option>
              </select>
            </div>
            
            <div className="flex items-center gap-4 pt-2">
              <div className="flex-grow border border-gray-300 rounded p-2 text-sm bg-gray-50">
                <input type="file" className="text-xs file:mr-4 file:py-2 file:px-4 file:rounded file:border-0 file:text-xs file:font-semibold file:bg-neutral-900 file:text-white hover:file:bg-neutral-800 cursor-pointer" onChange={e => setForm({...form, image: e.target.files[0]})} required={!editingCarId} />
              </div>
              <button type="submit" className="bg-neutral-900 text-white font-bold uppercase tracking-wider text-xs px-8 py-4 rounded hover:bg-neutral-800 transition">
                {editingCarId ? 'Update Asset' : 'Deploy Asset'}
              </button>
              {editingCarId && (
                <button type="button" onClick={resetFormState} className="border border-gray-300 text-neutral-700 font-bold uppercase tracking-wider text-xs px-6 py-4 rounded hover:bg-gray-100 transition">
                  Cancel
                </button>
              )}
            </div>
          </form>
        </div>

        {/* ACTIVE FLEET REGISTERS TABLE DATA LAYOUT CONTAINER */}
        <div className="bg-white border rounded-xl p-8 shadow-sm">
          <h3 className="text-xl font-black uppercase text-neutral-900 tracking-tight mb-6">Active Fleet Registers</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="border-b text-gray-400 font-bold uppercase tracking-wider text-[11px]">
                  <th className="pb-3 w-1/3">Car Details</th>
                  <th className="pb-3">Plate</th>
                  <th className="pb-3">Rate (PKR)</th>
                  <th className="pb-3">Status Dropdown Selector</th>
                  <th className="pb-3 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y text-neutral-900 font-medium">
                {cars.map(car => (
                  <tr key={car._id} className="hover:bg-gray-50/50 transition-colors">
                    <td className="py-4 font-bold">
                      {car.brand} - {car.name} <span className="text-xs text-gray-400 font-normal">({car.color})</span>
                      <span className="block text-[10px] text-gray-400 uppercase font-extrabold tracking-widest mt-0.5">{car.category || 'Standard'}</span>
                    </td>
                    <td className="py-4 font-mono text-xs text-gray-500">{car.numberPlate}</td>
                    <td className="py-4 text-xs font-bold text-gray-700">Rs. {car.pricePerHour?.toLocaleString() || '0'}/hr</td>
                    <td className="py-4">
                      <select 
                        value={car.status} 
                        onChange={(e) => handleStatusChange(car._id, e.target.value)}
                        className={`text-xs font-bold uppercase rounded-md py-1.5 px-3 border focus:outline-none ${car.status === 'available' ? 'bg-green-50 border-green-200 text-green-700' : 'bg-red-50 border-red-200 text-red-700'}`}
                      >
                        <option value="available">🟢 Available</option>
                        <option value="appointed">🔴 Appointed</option>
                      </select>
                    </td>
                    <td className="py-4 text-right space-x-3">
                      {/* ADDED EDIT INTERACTION CONTROL BUTTON */}
                      <button 
                        onClick={() => handleEditInit(car)} 
                        className="text-xs font-bold uppercase text-blue-600 hover:text-blue-800 transition tracking-wide"
                      >
                        Edit
                      </button>
                      <button 
                        onClick={() => handleDeleteAsset(car._id)} 
                        className="text-xs font-bold uppercase text-red-600 hover:text-red-800 transition tracking-wide"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}
